namespace CommunityOS.Application.Files;

/// <summary>
/// Storage seam for the raw file bytes, kept deliberately narrow so the local-filesystem
/// implementation used now can be swapped for a cloud blob store (S3 / Azure Blob) later without
/// touching <see cref="IFileService"/> or any caller (ponytail: local now, seam for cloud). The
/// store owns <i>only</i> the bytes keyed by an opaque <c>storageKey</c>; all metadata, tenant and
/// permission concerns live in <see cref="IFileService"/>.
///
/// <para>The key is generated by the store (never derived from a client-supplied file name), and
/// the store resolves it to a non-publicly-browsable location — outside the web root, not served
/// statically (Req 7.4). Implementations stream rather than buffer the whole file in memory where
/// practical, and MUST guard against path traversal when turning a key into a physical location.</para>
/// </summary>
public interface IFileBlobStore
{
    /// <summary>
    /// Persist <paramref name="content"/> and return a freshly generated opaque storage key that
    /// <see cref="OpenAsync"/> can later resolve. The stream is read from its current position to
    /// the end. The returned key is safe to persist as metadata and is never a public URL.
    /// </summary>
    Task<string> SaveAsync(Stream content, CancellationToken cancellationToken = default);

    /// <summary>
    /// Open a readable stream over the bytes previously stored under <paramref name="storageKey"/>.
    /// Returns null when nothing is stored under the key. The caller owns disposing the stream.
    /// </summary>
    Task<Stream?> OpenAsync(string storageKey, CancellationToken cancellationToken = default);
}
